From 3a061c367dc2654b9c3e14af62ce7adbd971fe7f Mon Sep 17 00:00:00 2001
From: Brandon L Black <blblack@gmail.com>
Date: Mon, 31 Mar 2014 17:58:20 -0500
Subject: [PATCH] fix kill-status bug from 2ae7c831


diff --git a/gdnsd/libgdnsd/libdmn/dmn.c b/gdnsd/libgdnsd/libdmn/dmn.c
index fe6b04f..7f8d654 100644
--- a/gdnsd/libgdnsd/libdmn/dmn.c
+++ b/gdnsd/libgdnsd/libdmn/dmn.c
@@ -366,7 +366,7 @@ static bool terminate_pid_and_wait(pid_t pid) {
             tv.tv_sec = 0;
             tv.tv_usec = 100000;
             select(0, NULL, NULL, NULL, &tv);
-            if(!kill(pid, 0)) {
+            if(kill(pid, 0)) {
                 still_running = false;
                 break;
             }
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by an incorrect condition in the `if` statement that checked the status of a process. The original code used `if(!kill(pid, 0))`, which incorrectly interpreted a successful `kill` call (indicating the process was running) as the process not being active. This led to incorrect handling of process termination status. The fix changes the condition to `if(kill(pid, 0))`, which correctly identifies when a process is still running.

        Commit message:
        fix kill-status bug from 2ae7c831  

        Patch:
         // True retval indicates daemon is still running
 static bool terminate_pid_and_wait(pid_t pid) {
     dmn_assert(pid); // don't try to kill (0, ...)

     bool still_running = false;

     if(!kill(pid, SIGTERM)) {
         still_running = true;
         struct timeval tv;
         unsigned tries = 150;
         while(tries--) {
             tv.tv_sec = 0;
             tv.tv_usec = 100000;
             select(0, NULL, NULL, NULL, &tv);
-            if(!kill(pid, 0)) {
+            if(kill(pid, 0)) {
                 still_running = false;
                 break;
             }
         }
     }

     return still_running;
 }



        Provide a response strictly in the following format:
